;-----------------------------------------------------------------------------
;  FUNCTION NAME: EzI2C_Start
;
;  DESCRIPTION:
;   Initialize the EzI2C I2C bus interface.
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:
;
;  RETURNS: none
;
;  SIDE EFFECTS:
;    REGISTERS ARE VOLATILE: THE A AND X REGISTERS MAY BE MODIFIED!
;    IN THE LARGE MEMORY MODEL CURRENTLY ONLY THE PAGE POINTER 
;    REGISTERS LISTED BELOW ARE MODIFIED.  THIS DOES NOT GUARANTEE 
;    THAT IN FUTURE IMPLEMENTATIONS OF THIS FUNCTION OTHER PAGE POINTER 
;    REGISTERS WILL NOT BE MODIFIED.
;          
;    Page Pointer Registers Modified: 
;          CUR_PP
;
;  THEORY of OPERATION or PROCEDURE:
;

 EzI2C_Start:
_EzI2C_Start:

   RAM_PROLOGUE RAM_USE_CLASS_4
   RAM_SETPAGE_CUR >EzI2C_varPage
   
IF (EzI2C_DYNAMIC_ADDR)  ;; DYNAMIC ADDRESS
IF (EzI2C_AUTO_ADDR_CHECK^1) ;; for CY8C28X45 chip: do not touch the EzI2C_bAddr variable if AutoAddressCompare feature is enabled.
   mov  [EzI2C_bAddr],EzI2C_SLAVE_ADDR
ENDIF   
ENDIF
IF (EzI2C_CY8C22x45)
   M8C_SetBank1
   mov   reg[EzI2C_ADDR_REG], (EzI2C_SLAVE_ADDR>>1)
   M8C_SetBank0
ENDIF

   M8C_SetBank1 ;The SDA and SCL pins are setting to Hi-z drive mode
   and reg[EzI2CSDA_DriveMode_0_ADDR],~(EzI2CSDA_MASK|EzI2CSCL_MASK)
   or  reg[EzI2CSDA_DriveMode_1_ADDR], (EzI2CSDA_MASK|EzI2CSCL_MASK)
   M8C_SetBank0
   or  reg[EzI2CSDA_DriveMode_2_ADDR], (EzI2CSDA_MASK|EzI2CSCL_MASK)

   mov  [EzI2C_bState],0x00    ;; Make sure state machine is initialized
   mov [EzI2C_bBusy_Flag],EzI2C_I2C_FREE ;; Clear Busy flag

   call EzI2C_EnableInt
   call EzI2C_EnableSlave

   nop
   nop
   nop
   nop
   nop
   
   mov A, 0
   mov [EzI2C_bRAM_RWoffset], A
IF (EzI2C_ROM_ENABLE)
   mov [EzI2C_bROM_RWoffset], A
ENDIF
   
   M8C_SetBank1 ;The SDA and SCL pins are restored to Open Drain Low drive mode
   or reg[EzI2CSDA_DriveMode_0_ADDR], (EzI2CSDA_MASK|EzI2CSCL_MASK)
   or reg[EzI2CSDA_DriveMode_1_ADDR], (EzI2CSDA_MASK|EzI2CSCL_MASK)
   M8C_SetBank0
   or reg[EzI2CSDA_DriveMode_2_ADDR], (EzI2CSDA_MASK|EzI2CSCL_MASK)

   RAM_EPILOGUE RAM_USE_CLASS_4
   ret

.ENDSECTION

IF (EzI2C_DYNAMIC_ADDR | EzI2C_AUTO_ADDR_CHECK) ;; Enable this function if Address is Dynamic or the AUTO_ADDR_CHECK is enabled
.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: EzI2C_SetAddr(BYTE bAddr)
;
;  DESCRIPTION:
;   Set the I2C slave address for the EzI2C I2C bus interface.
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:
;      A =>  Slave address
;
;  RETURNS: none
;
;  SIDE EFFECTS;    
;    REGISTERS ARE VOLATILE: THE A AND X REGISTERS MAY BE MODIFIED!
;    IN THE LARGE MEMORY MODEL CURRENTLY ONLY THE PAGE POINTER 
;    REGISTERS LISTED BELOW ARE MODIFIED.  THIS DOES NOT GUARANTEE 
;    THAT IN FUTURE IMPLEMENTATIONS OF THIS FUNCTION OTHER PAGE POINTER 
;    REGISTERS WILL NOT BE MODIFIED.
;          
;    Page Pointer Registers Modified: 
;          CUR_PP
;
;  THEORY of OPERATION or PROCEDURE:
;

 EzI2C_SetAddr:
_EzI2C_SetAddr:
   RAM_PROLOGUE RAM_USE_CLASS_4
IF (EzI2C_AUTO_ADDR_CHECK^1) ;; for CY8C28X45 chip: do not touch the EzI2C_bAddr variable if AutoAddressCompare feature is enabled.
   RAM_SETPAGE_CUR >EzI2C_bAddr
 IF (EzI2C_CY8C22x45)
   and   A, ~EzI2C_HW_ADDR_EN
   M8C_SetBank1
   mov   reg[EzI2C_ADDR_REG], A
   M8C_SetBank0
 ENDIF
   asl   A
   mov   [EzI2C_bAddr],A
ELSE                          ;; write to the ADDR register instead
   RAM_PROLOGUE RAM_USE_CLASS_2
   and  A, ~EzI2C_HW_ADDR_MASK	; verify address value
   mov  X, SP
   push A                                   ; store address value
   M8C_SetBank1               ;; Set Bank 1
   mov  A, reg[EzI2C_ADDR_REG]   ; get value from address register
   and  A, EzI2C_HW_ADDR_MASK    ; define highest bit
   or   A, [X]                              ; form address value 	
   mov  reg[EzI2C_ADDR_REG], A   ; set new address value to register
   M8C_SetBank0               ;; Set Bank 0
   pop  A
   RAM_EPILOGUE RAM_USE_CLASS_2
ENDIF
   RAM_EPILOGUE RAM_USE_CLASS_4
   ret

.ENDSECTION
ENDIF

.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME:BYTE EzI2C_GetActivity(void)
;
;  DESCRIPTION:
;    Return a non-zero value if the I2C hardware has seen activity on the bus.
;    The activity flag will be cleared if set when calling this function.
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:  none
;
;  RETURNS: 
;    BYTE  non-zero = Activity
;          zero     = No Activity
;
;  SIDE EFFECTS;    
;    REGISTERS ARE VOLATILE: THE A AND X REGISTERS MAY BE MODIFIED!
;    IN THE LARGE MEMORY MODEL CURRENTLY ONLY THE PAGE POINTER 
;    REGISTERS LISTED BELOW ARE MODIFIED.  THIS DOES NOT GUARANTEE 
;    THAT IN FUTURE IMPLEMENTATIONS OF THIS FUNCTION OTHER PAGE POINTER 
;    REGISTERS WILL NOT BE MODIFIED.
;          
;    Page Pointer Registers Modified: 
;          CUR_PP
;
;  THEORY of OPERATION or PROCEDURE:
;

 EzI2C_GetActivity:
_EzI2C_GetActivity:
   RAM_PROLOGUE RAM_USE_CLASS_4
   RAM_SETPAGE_CUR >EzI2C_bState
   mov   A,[EzI2C_bState]
   and   A,EzI2C_ACTIVITY_MASK         ; Mask off activity bits
   and   [EzI2C_bState],~EzI2C_ACTIVITY_MASK ; Clear system activity bits

EzI2C_GetActivity_End:
   RAM_EPILOGUE RAM_USE_CLASS_4
   ret

.ENDSECTION

.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: BYTE EzI2C_GetAddr(Void)
;
;  DESCRIPTION:
;   Get the I2C slave address for the EzI2C I2C bus interface.
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS: none
;
;  RETURNS: none
;
;  SIDE EFFECTS;    
;    REGISTERS ARE VOLATILE: THE A AND X REGISTERS MAY BE MODIFIED!
;    IN THE LARGE MEMORY MODEL CURRENTLY ONLY THE PAGE POINTER 
;    REGISTERS LISTED BELOW ARE MODIFIED.  THIS DOES NOT GUARANTEE 
;    THAT IN FUTURE IMPLEMENTATIONS OF THIS FUNCTION OTHER PAGE POINTER 
;    REGISTERS WILL NOT BE MODIFIED.
;          
;    Page Pointer Registers Modified: 
;          CUR_PP
;
;
;  THEORY of OPERATION or PROCEDURE:
;

 EzI2C_GetAddr:
_EzI2C_GetAddr:

IF (EzI2C_DYNAMIC_ADDR | EzI2C_AUTO_ADDR_CHECK) ;; if Address is Dynamic or the AUTO_ADDR_CHECK is enabled
   RAM_PROLOGUE RAM_USE_CLASS_4
IF (EzI2C_AUTO_ADDR_CHECK^1) ;; for CY8C28X45 chip: do not touch the EzI2C_bAddr variable if AutoAddressCompare feature is enabled.
   RAM_SETPAGE_CUR >EzI2C_bAddr
   mov   A,[EzI2C_bAddr]
   asr   A                          ; Shift Addr to right to drop RW bit.
ELSE                          ;; read the address from ADDR register instead
   M8C_SetBank1               ;; Set Bank 1 
   mov A, reg[EzI2C_ADDR_REG]
   M8C_SetBank0               ;; Set Bank 0
ENDIF
   and   A, 0x7f              ; Mask off bogus MSb
   RAM_EPILOGUE RAM_USE_CLASS_4
ELSE
   mov   A,0x4            
ENDIF
   ret

.ENDSECTION



.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: EzI2C_EnableInt
;  FUNCTION NAME: EzI2C_ResumeInt
;  DESCRIPTION:
;     Enables SDA interrupt allowing start condition detection. Remember to call the
;     global interrupt enable function by using the macro: M8C_EnableGInt.
;	  EzI2C_ResumeInt performs the enable int function without fist clearing
;     pending interrupts.
;-----------------------------------------------------------------------------
;
;  ARGUMENTS: none
;
;  RETURNS: none
;
;  SIDE EFFECTS: REGISTERS ARE VOLATILE: THE A AND X REGISTERS MAY BE MODIFIED!
;
;  THEORY of OPERATION or PROCEDURE:
;
 EzI2C_ResumeInt:
_EzI2C_ResumeInt:
   RAM_PROLOGUE RAM_USE_CLASS_1
   jmp   ResumeEntry

 EzI2C_EnableInt:
_EzI2C_EnableInt:
   RAM_PROLOGUE RAM_USE_CLASS_1
   ;first clear any pending interrupts
   M8C_ClearIntFlag INT_CLR3, EzI2C_INT_MASK   
ResumeEntry:
   M8C_EnableIntMask EzI2C_INT_REG, EzI2C_INT_MASK
   RAM_EPILOGUE RAM_USE_CLASS_1
   ret

.ENDSECTION

.SECTION
;-----------------------------------------------------------------------------
;  FUNCTION NAME: EzI2C_EnableSlave
;
;  DESCRIPTION:
;     Enables SDA interrupt allowing start condition detection. Remember to call the
;     global interrupt enable function by using the macro: M8C_EnableGInt.
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS: none
;
;  RETURNS: none
;
;  SIDE EFFECTS: REGISTERS ARE VOLATILE: THE A AND X REGISTERS MAY BE MODIFIED!
;
;  THEORY of OPERATION or PROCEDURE:
;

 EzI2C_EnableSlave:
_EzI2C_EnableSlave:

    RAM_PROLOGUE RAM_USE_CLASS_1
    
    IF (EzI2C_CY8C27XXXA_ID) ;; Enable this code if we have CY8C27XXXA chip ID
    ; Save original CPU clock speed
    M8C_SetBank1          ; Set Bank 1 
    mov  A,reg[OSC_CR0]   ; Get current configuration of OSC_CR0 (Bank 1)
    push A                ; Save OSC_CR0 configuration
    and  A,0xF8           ; Mask off CPU speed
    or   A,0x05           ; Set clock to 750KHz
    mov  reg[OSC_CR0],A   ; Write new value to OSC_CR0 (Bank 1)
    M8C_SetBank0          ; Back to Bank 0
    ENDIF 
    ; Enable I2C Slave
    IF(EzI2C_USED_I2C_BLOCK)
    M8C_SetBank1
    or   reg[EzI2C_CFG_REG],(EzI2C_CFG_Slave_EN | EzI2C_CFG_BUS_ERROR_IE | EzI2C_CFG_STOP_IE)
    M8C_SetBank0
    ELSE
    or   reg[EzI2C_CFG_REG],(EzI2C_CFG_Slave_EN | EzI2C_CFG_BUS_ERROR_IE | EzI2C_CFG_STOP_IE)
    ENDIF
    IF (EzI2C_CY8C27XXXA_ID) ;; Enable this code if we have CY8C27XXXA chip ID    
    ; Restore original CPU clock speed
    pop  A
    M8C_SetBank1          ; Set Bank 1
    mov  reg[OSC_CR0],A   ; Restore
    M8C_SetBank0          ; Back to Bank 0
    ENDIF    
    RAM_EPILOGUE RAM_USE_CLASS_1
    ret

.ENDSECTION

